--[[
    WoWGear · 装备库（自动生成，不要手改）

    由 src/build/export_addon_lib.py 从 data/wowgear.db 导出。
    换赛季要重新导：python src/build/export_addon_lib.py

    格式：[itemID] = { 名字, 基础装等, 品质, 槽位, 物品类型, {[statID]=分配权重}, 是否本赛季 }

    **存的是分配权重（万分比），不是属性数值**。真实数值 =
    权重 × 装等系数 × 1e-4，系数由 Curve.lua 按装等插值给出。
    存权重而不是存数值，是为了让候选装备能按任意装等重算——
    库里各赛季的基础装等是混的（59/108/197/298），
    直接拿各自身装等比会得出「装等低的就是差」这种废话。
]]

